/*
 * ============================================================================
 *  Thue-Morse Sequence Generator & Properties
 * ============================================================================
 *
 *  The Thue-Morse sequence (A010060) is a binary sequence defined by:
 *    t(0) = 0
 *    t(n) = popcount(n) mod 2     (parity of the number of 1-bits of n)
 *
 *  Equivalently, it can be generated by the substitution rule:
 *    0 -> 01,  1 -> 10
 *  Starting from "0": 0, 01, 0110, 01101001, ...
 *
 *  Properties:
 *  - Overlap-free: no substring of the form aXaXa exists.
 *  - It is the fixed point of the morphism 0->01, 1->10.
 *  - Used in fair division (Thue-Morse fairness), combinatorics on words,
 *    chess tournament scheduling, and fractal generation.
 *  - The sequence is cube-free (no substring www exists).
 *  - Related to the Prouhet-Thue-Morse problem: for any k, the first 2^k
 *    terms can be split into two groups with equal sums of j-th powers
 *    for j = 0, 1, ..., k-1.
 *
 *  Time Complexity:  O(N) to generate N terms
 *  Space Complexity: O(N)
 * ============================================================================
 */

#include <iostream>
#include <vector>
#include <string>
#include <cstdint>
#include <iomanip>

namespace thue_morse {

/* Generate using popcount parity */
int thueMorseBit(int64_t n) {
    int count = 0;
    while (n > 0) {
        count += static_cast<int>(n & 1);
        n >>= 1;
    }
    return count & 1;
}

std::vector<int> generateSequence(int length) {
    std::vector<int> seq(length);
    for (int i = 0; i < length; ++i) {
        seq[i] = thueMorseBit(i);
    }
    return seq;
}

/* Generate via substitution morphism */
std::string generateBySubstitution(int iterations) {
    std::string s = "0";
    for (int i = 0; i < iterations; ++i) {
        std::string next;
        next.reserve(s.size() * 2);
        for (char c : s) {
            next += (c == '0') ? "01" : "10";
        }
        s = next;
    }
    return s;
}

/* Check cube-freeness: no substring of form www */
bool isCubeFree(const std::vector<int>& seq) {
    int n = static_cast<int>(seq.size());
    for (int len = 1; len * 3 <= n; ++len) {
        for (int start = 0; start + 3 * len <= n; ++start) {
            bool isCube = true;
            for (int j = 0; j < len && isCube; ++j) {
                if (seq[start + j] != seq[start + len + j] ||
                    seq[start + j] != seq[start + 2 * len + j]) {
                    isCube = false;
                }
            }
            if (isCube) return false;
        }
    }
    return true;
}

/*
 * Verify Prouhet-Thue-Morse property for power k:
 * Indices where t(i)=0 and where t(i)=1, when considering
 * the first 2^k values, have equal sums of j-th powers for j < k.
 */
bool verifyProuhetProperty(int k) {
    int n = 1 << k;
    auto seq = generateSequence(n);

    for (int power = 0; power < k; ++power) {
        int64_t sum0 = 0, sum1 = 0;
        for (int i = 0; i < n; ++i) {
            int64_t val = 1;
            for (int p = 0; p < power; ++p) val *= i;

            if (seq[i] == 0) sum0 += val;
            else sum1 += val;
        }
        if (sum0 != sum1) return false;
    }
    return true;
}

} // namespace thue_morse

int main() {
    std::cout << "========================================================\n";
    std::cout << "  Thue-Morse Sequence Generator & Properties\n";
    std::cout << "========================================================\n\n";

    /* Generate first 64 terms */
    int length = 64;
    auto seq = thue_morse::generateSequence(length);

    std::cout << "First " << length << " terms of the Thue-Morse sequence:\n";
    for (int i = 0; i < length; ++i) {
        std::cout << seq[i];
        if ((i + 1) % 32 == 0) std::cout << "\n";
    }
    std::cout << "\n";

    /* Substitution morphism comparison */
    std::cout << "Substitution morphism (5 iterations):\n";
    for (int iter = 0; iter <= 5; ++iter) {
        std::string s = thue_morse::generateBySubstitution(iter);
        std::cout << "  Iter " << iter << " (len " << std::setw(2)
                  << s.size() << "): ";
        if (s.size() <= 40) {
            std::cout << s;
        } else {
            std::cout << s.substr(0, 32) << "... (truncated)";
        }
        std::cout << "\n";
    }

    /* Verify popcount and substitution produce the same sequence */
    std::cout << "\nVerify popcount == substitution for first 32 terms: ";
    auto subst = thue_morse::generateBySubstitution(5);
    bool match = true;
    for (int i = 0; i < 32; ++i) {
        if (seq[i] != (subst[i] - '0')) { match = false; break; }
    }
    std::cout << (match ? "PASSED" : "FAILED") << "\n";

    /* Cube-freeness check */
    std::cout << "Cube-free check (first 64 terms): "
              << (thue_morse::isCubeFree(seq) ? "YES (cube-free)" : "NO") << "\n";

    /* Balance check: equal number of 0s and 1s in blocks of size 2^k */
    std::cout << "\nBalance check (count of 0s and 1s in first 2^k terms):\n";
    for (int k = 1; k <= 6; ++k) {
        int n = 1 << k;
        int zeros = 0, ones = 0;
        for (int i = 0; i < n; ++i) {
            if (seq[i] == 0) ++zeros; else ++ones;
        }
        std::cout << "  2^" << k << " = " << std::setw(2) << n
                  << ": zeros=" << zeros << " ones=" << ones
                  << (zeros == ones ? " (balanced)" : " (imbalanced)") << "\n";
    }

    /* Prouhet-Thue-Morse property */
    std::cout << "\nProuhet-Thue-Morse equal power sums property:\n";
    for (int k = 1; k <= 6; ++k) {
        bool ok = thue_morse::verifyProuhetProperty(k);
        std::cout << "  k = " << k << ": " << (ok ? "PASSED" : "FAILED") << "\n";
    }

    return 0;
}
